import{_ as t}from"./chunks/image-002.Dp2-bnLm.js";import{_ as a,o as _,c as e,a3 as o}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/42-除狭第三十二.md","filePath":"books/yan-tie-lun/42-除狭第三十二.md","lastUpdated":1794316978000}'),n={name:"books/yan-tie-lun/42-除狭第三十二.md"};function s(r,p,i,l,c,d){return _(),e("div",null,[...p[0]||(p[0]=[o('<p>除狭第三十二 【题解】</p><p>在《箴石》中，贤良感叹“君子之路，行止之道固狭耳”。本篇紧承上文，大夫以郡守、国相为例，说他们处于古代方伯的地位，接受天子之命，独断专行，统治千里之地，不受朝廷钳制。大夫进而指出，人之善恶穷通全在自己，不能说人生道路狭窄。贤良则认为，当代朝廷已经抛弃了古代层层选拔贤能的优良传统，选吏之道混乱，公开卖官鬻爵，一批无才无德的封疆大吏统治千里之域，独揽民众生杀大权，这是造成社会混乱的根本原因。贤良提出，朝廷选贤要出自公心，悬赏以等待民众立功，排列爵位来等候贤能，推举善人如恐不足，罢免恶人如同对待仇敌，这样才能建立清明的吏治。</p><p>大夫曰：“贤者处大林[(1)]，遭风雷而不迷[(2)]。愚者虽处平敞大路，犹暗惑焉。今守、相亲剖符赞拜[(3)]，莅一郡之众[(4)]，古方伯之位也[(5)]。受命专制[(6)]，宰割千里[(7)]，不御于内[(8)]；善恶在于己，己不能故耳[(9)]，道何狭之有哉？”</p><p>【注释】</p><p>[(1)]大林：大麓，大山深林。</p><p>[(2)]遭风雷不迷：《尚书·尧典》：“纳于大麓，烈风雷雨弗迷。”此处用舜入大麓典故。</p><p>[(3)]守：郡守。相：国相。亲：亲自。剖符：古代天子分封诸侯功臣，在长六寸的竹片上书写封委命令，然后将竹片一分为二，天子与诸侯功臣各执一半，两片相合作为凭证。赞：指赞礼之人。拜：拜官。</p><p>[(4)]莅（lì）：莅临，君临。</p><p>[(5)]方伯：商周时期的诸侯之长。</p><p>[(6)]专制：独断。</p><p>[(7)]宰割：本指分割牲畜，此处指统治。</p><p>[(8)]御：节制。内：指朝廷。</p><p>[(9)]故：缘故。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“贤士处于大山深林，遭遇暴风雷雨而不会迷失方向。愚昧的人即使是走在平坦宽敞的大路上，仍然会感到昏暗迷惑。现在，郡守、国相亲自与天子分剖信符，接受赞礼拜官，他们莅临一郡民众之上，这相当于古代诸侯方伯的地位啊。他们受天子之命，独断专行，统治千里之地，不受朝廷钳制；名声或善或恶，全在于自己，恶名是由于自己没有能力的缘故，哪里有什么道路狭窄之说呢？”</p><p>贤良曰：“古之进士也[(1)]，乡择而里选[(2)]，论其才能，然后官之，胜职任然后爵而禄之[(3)]。故士修之乡曲[(4)]，升诸朝廷，行之幽隐[(5)]，明足显著[(6)]。疏远无失士[(7)]，小大无遗功[(8)]。是以贤者进用，不肖者简黜[(9)]。今吏道杂而不选[(10)]，富者以财贾官[(11)]，勇者以死射功[(12)]。戏车鼎跃[(13)]，咸出补吏[(14)]，累功积日[(15)]，或至卿相。垂青绳[(16)]，擐银龟[(17)]，擅杀生之柄[(18)]，专万民之命[(19)]。弱者，犹使羊将狼也[(20)]，其乱必矣。强者，则是予狂夫利剑也，必妄杀生也。是以往者，郡国黎民相乘而不能理[(21)]，或至锯颈杀不辜而不能正[(22)]。执纲纪非其道，盖博乱愈甚[(23)]。古者，封贤禄能，不过百里[(24)]；百里之中而为都，疆垂不过五十[(25)]，犹以为一人之身，明不能照[(26)]，聪不得达[(27)]，故立卿、大夫、士以佐之，而政治乃备[(28)]。今守、相或无古诸侯之贤，而莅千里之政，主一郡之众，施圣主之德，擅生杀之法，至重也。非仁人不能任，非其人不能行。一人之身，治乱在己，千里与之转化[(29)]，不可不熟择也。故人主有私人以财[(30)]，不私人以官，悬赏以待功，序爵以俟贤[(31)]，举善若不足，黜恶若仇雠[(32)]，固为其非功而残百姓也。夫辅主德[(33)]，开臣途，在于选贤而器使之[(34)]，择练守、相然后任之[(35)]。”</p><p>【注释】</p><p>[(1)]进士：选拔贤士。</p><p>[(2)]乡、里：古代基层行政单位，其管辖范围历代不同。《周礼·地官·大司徒》载一万二千五百家为乡。《周礼·地官·遂人》：“五家为邻，五邻为里。”以上为周代制度。《国语·齐语》：“五家为轨，轨为之长：十思为里，里有司；四里为连，连为之长；十里为乡，乡有良人焉。”这是春秋齐国制度。</p><p>[(3)]爵、禄：用做动词，授予爵位与俸禄。</p><p>[(4)]修：修养。乡曲：偏僻的地方，引申为乡里。</p><p>[(5)]幽隐：昏暗隐蔽，指偏远之地。</p><p>[(6)]明足显著：指贤士出仕之后处于众人瞩目的显著地位。明足，意为当官。</p><p>[(7)]疏远无失士：即使与朝廷关系疏远，也不要漏掉贤士。</p><p>[(8)]小大无遗功：无论功劳大小都不会遗漏。</p><p>[(9)]不肖：不似乃父，指不贤的人。简：检查。黜：罢免。</p><p>[(10)]杂：原作“壅”，据卢文弨说校改。选：挑选，选择。</p><p>[(11)]贾（ɡǔ）：买。</p><p>[(12)]以死射功：用死战来搏取功名。射，逐取。</p><p>[(13)]戏车：玩车技。鼎跃：举鼎。</p><p>[(14)]补吏：充当官吏。</p><p>[(15)]累功积日：一天天积累功劳资历。</p><p>[(16)]垂：垂挂。青绳：一本作“青绶”，系官印的青色绶带。</p><p>[(17)]擐（huàn）：贯，穿。银龟：《太平御览》六八三引《汉旧仪》：“御史，二千石，银印，龟纽，文曰章。”</p><p>[(18)]擅：独揽。杀生：犹言生死。柄：权柄。</p><p>[(19)]专：专断，与“擅”意同。</p><p>[(20)]羊将狼：比喻弱者统治强者。《史记·留侯世家》：“且太子所与皆诸将，皆尝与上定天下，今使太子将之，此无异使羊将狼也。”将，统率。</p><p>[(21)]黎民：老百姓。乘：侵陵。理：治理。</p><p>[(22)]锯颈：汉代锯脖子的酷刑。不辜：无罪。</p><p>[(23)]博乱：动乱。</p><p>[(24)]不过百里：《礼记·王制》：“公侯田方百里。”</p><p>[(25)]疆垂：边境。垂，通“陲”。</p><p>[(26)]明：视力。照：看到。</p><p>[(27)]聪：听力。</p><p>[(28)]政治：行政治理。备：完备。</p><p>[(29)]转化：随之变化。</p><p>[(30)]私人以财：用财富来奖赏所偏爱的人。《荀子·君道》：“故明主有私人以珠玉，无私人以官职事业。”私，个人偏爱。</p><p>[(31)]序爵：排列爵位。俟：等待。</p><p>[(32)]黜恶：罢免。仇雠：仇敌。</p><p>[(33)]辅：原作“傅”，据王利器说校改。</p><p>[(34)]器使：重用。</p><p>[(35)]择练：挑选。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“古代推贤进士，从乡到里，层层选择，评论其人的才能，然后给他官职，若能胜任职位，然后再封爵授禄。因此，贤士在乡里修炼道德才能，通过选择升到朝廷；在偏远之处修行，出仕之后则处于众人瞩目的显著地位。即使与朝廷关系疏远，录用时也不要漏掉贤士；无论功劳小大，奖赏时也不要有所遗漏。由此贤才得到提拔重用，不贤的人经检查后予以罢免。如今任用官吏之道杂乱无章，丢弃了传统的选拔做法，富人用钱买官，勇士通过死战求功。戏车玩鼎的杂技之人，都出来补任官吏，一天天积累功劳资历，有的人官至卿相。他们佩带青绶，贯穿银龟官印，独揽杀生权柄，专断万民性命。如果这些官员性格懦弱，那就如同让一只羊统率狼群，肯定会酿出混乱。如果这些官员性格强悍，那就等于授利剑给狂夫，肯定会胡乱杀人。因而过去郡县、侯国老百姓相互侵陵而得不到治理，有时候甚至锯脖子、杀无罪而得不到纠正。执掌国家纲纪的官员不由正道，大概社会混乱会越来越厉害。古时候，天子封爵贤能，方园不超过百里；在百里中心建立都城，从都城到边境不超过五十里，天子还以为仅凭诸侯一人之身，视力有看不到的地方，听力有达不到的地方，因而设立卿、大夫、士来辅佐诸侯，这样诸侯国的行政治理才算完备。如今郡守、国相可能不及古代诸侯贤能，却让他们主管千里政务，主宰一郡民众，要求他们广施圣主恩德，独揽生杀法令，使命极为重大啊。如果不是仁人就不能胜任郡守和国相，如果不是贤人就不能施行正确的治理。郡守、相国以一人之身，治和乱全在于郡守、国相自己，方园千里的治乱都随着郡守、国相一人才德而变化，这样的职位是不可以不认真选择的。所以人主可以用财富来奖赏他所偏爱的人，而不是用官爵来奖赏他所偏爱的人，朝廷悬赏以等待民众立功，排列爵位来等候贤能，推举善人如恐不足，罢免恶人如同对待仇敌，这本来就是因为恶人没有功劳而残害百姓啊。辅佐君主的德政，开通臣民的仕途，在于选用贤能，重用他们，挑选郡守、国相然后加以任用。”</p>',56)])])}const T=a(n,[["render",s]]);export{u as __pageData,T as default};
